pub enum Cmd {
    /// Up by n steps (`/forward/<n>`: upstream's `Level::High`, as `Raise`).
    Forward(u32),
    /// Down by n steps (`/backward/<n>`).
    Backward(u32),
    Raise,
    Lower,
}

