plan.kernel_code:
pub fn plan(st: &Blind, cmd: &Cmd) -> (Blind, Move) {
    match cmd {
        Cmd::Forward(n) => {
            let n = min(*n, BLIND_HEIGHT);
            let pos = if st.pos > n { st.pos - n } else { 0 };
            (Blind { pos }, Move { up: true, steps: n })
        }
        Cmd::Backward(n) => {
            let n = min(*n, BLIND_HEIGHT);
            let pos = st.pos.saturating_add(n);
            (Blind { pos }, Move { up: false, steps: n })
        }
        Cmd::Raise => (Blind { pos: 0 }, Move { up: true, steps: min(st.pos, BLIND_HEIGHT) }),
        Cmd::Lower => {
            if st.pos >= BLIND_HEIGHT {
                (*st, Move { up: false, steps: 0 })
            } else {
                (Blind { pos: BLIND_HEIGHT }, Move { up: false, steps: BLIND_HEIGHT - st.pos })
            }
        }
    }
}

