microsteps.kernel_code:
pub fn microsteps(steps: u32, per_step: u32) -> u32 {
    // Widened: a u32 product fits a u64 (Aeneas has no model of
    // `u32::saturating_mul`; this is the same function).
    let wide = steps as u64 * per_step as u64;
    if wide > u32::MAX as u64 { u32::MAX } else { wide as u32 }
}

microsteps.lean:
def microsteps (steps : Std.U32) (per_step : Std.U32) : Result Std.U32 := do
  let i ← lift (UScalar.cast .U64 steps)
  let i1 ← lift (UScalar.cast .U64 per_step)
  let wide ← i * i1
  let i2 ← lift (UScalar.cast .U64 core.num.U32.MAX)
  if wide > i2
  then ok core.num.U32.MAX
  else ok (UScalar.cast .U32 wide)

